(368221, 30667, 5728, '<td valign="top">This is a fantastic photo for this week''s challenge, the sepia works so well. I like the effect of the reflections in the sides giving the impression of many escalators side by side. One of my favourites so far - 10.</td>', 'This is a fantastic photo for this week''s challenge, the sepia works so well. I like the effect of the reflections in the sides giving the impression of many escalators side by side. One of my favourites so far - 10.', '2003-07-28 03:50:33.000000', NULL, 1),
(368222, 30339, 8860, '<td valign="top">The dark, vignetted border makes the image look dirty. The desaturation also reduces the richness of the shot.</td>', 'The dark, vignetted border makes the image look dirty. The desaturation also reduces the richness of the shot.', '2003-07-28 03:50:59.000000', NULL, 1),
(368223, 30771, 8860, '<td valign="top">Shame you couldn''t get in a bit closer to remove even more context around the structure. Possibly centering the shot could have helped too. If you''d angled the camera upwards the vertical struts would have added more dynamics.</td>', 'Shame you couldn''t get in a bit closer to remove even more context around the structure. Possibly centering the shot could have helped too. If you''d angled the camera upwards the vertical struts would have added more dynamics.', '2003-07-28 03:52:48.000000', NULL, 1),
