(369141, 30580, 10275, '<td valign="top">This is such a good shot, and it made me laugh too (very clever title). This is definitely 10.</td>', 'This is such a good shot, and it made me laugh too (very clever title). This is definitely 10.', '2003-07-28 23:24:43.000000', NULL, 1),
