(369465, 30260, 6870, '<td valign="top">Clever idea! I wish it were sharper and with more interesting light, but your composition works well, and the cropping is  just right.</td>', 'Clever idea! I wish it were sharper and with more interesting light, but your composition works well, and the cropping is  just right.', '2003-07-29 10:01:48.000000', NULL, 1),
(369467, 30590, 6870, '<td valign="top">I totally agree! Nice curve here. Light seems just a tad harsh, but wonderful composition and colors.</td>', 'I totally agree! Nice curve here. Light seems just a tad harsh, but wonderful composition and colors.', '2003-07-29 10:02:37.000000', NULL, 1),
