(369494, 30776, 10608, '<td valign="top">I love the composition of color in this photo.</td>', 'I love the composition of color in this photo.', '2003-07-29 10:33:36.000000', NULL, 1),
(369499, 30691, 2716, '<td valign="top">Love the symmetry.  Very interesting.  9  Jacko.</td>', 'Love the symmetry.  Very interesting.  9  Jacko.', '2003-07-29 10:39:17.000000', NULL, 1),
(369514, 30579, 5728, '<td valign="top">Original. Focused. Well done. I am looking forward to seeing who took this :-)</td>', 'Original. Focused. Well done. I am looking forward to seeing who took this :-)', '2003-07-29 11:18:52.000000', NULL, 1),
