(369719, 30590, 10250, '<td valign="top">Having three snakes of my own, and a passion for herpetology, I was drawn to this picture. I find the hot spots on the scales, and the bright, washed out background to be a little distracting. I photograph a lot of snakes in the wild, and it''s not an easy task, so I still think this picture is worthy of a 9.</td>', 'Having three snakes of my own, and a passion for herpetology, I was drawn to this picture. I find the hot spots on the scales, and the bright, washed out background to be a little distracting. I photograph a lot of snakes in the wild, and it''s not an easy task, so I still think this picture is worthy of a 9.', '2003-07-29 17:04:50.000000', NULL, 1),
(369819, 30687, 3724, '<td valign="top">fridge doors should be a challenge in its own right.......</td>', 'fridge doors should be a challenge in its own right.......', '2003-07-29 20:32:09.000000', NULL, 1),
(369820, 30743, 3724, '<td valign="top">tractor detail........  interesting composition</td>', 'tractor detail........  interesting composition', '2003-07-29 20:34:18.000000', NULL, 1),
(369826, 30772, 3724, '<td valign="top">good title........</td>', 'good title........', '2003-07-29 20:41:14.000000', NULL, 1),
(369847, 30765, 3290, '<td valign="top">Very nice. Great composition, nice use of DOF and the lighting is just right. Not much to fault here. Well done.</td>', 'Very nice. Great composition, nice use of DOF and the lighting is just right. Not much to fault here. Well done.', '2003-07-29 20:54:34.000000', NULL, 1),
(369848, 30750, 3290, '<td valign="top">Attractive, but slightly dark and could do with a tad more contrast. I think I''d also have rotated slightly so that the line of the nose and a line across the eyes form diagonals across the picture. Nice, though.</td>', 'Attractive, but slightly dark and could do with a tad more contrast. I think I''d also have rotated slightly so that the line of the nose and a line across the eyes form diagonals across the picture. Nice, though.', '2003-07-29 20:55:51.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(369882, 30579, 1467, '<td valign="top">Nice colors and contrast</td>', 'Nice colors and contrast', '2003-07-29 21:27:17.000000', NULL, 1),
(369884, 30238, 1467, '<td valign="top">Nicely done, good clarity</td>', 'Nicely done, good clarity', '2003-07-29 21:28:04.000000', NULL, 1),
(369886, 30769, 1467, '<td valign="top">Excellent color. Nice focus and perspective</td>', 'Excellent color. Nice focus and perspective', '2003-07-29 21:29:40.000000', NULL, 1),
(369887, 30722, 1467, '<td valign="top">I like the focal point</td>', 'I like the focal point', '2003-07-29 21:30:46.000000', NULL, 1),
(369889, 30702, 1467, '<td valign="top">Wonderful color and perspective, very creative</td>', 'Wonderful color and perspective, very creative', '2003-07-29 21:31:44.000000', NULL, 1),
(369958, 30578, 2333, '<td valign="top">I really like this subject and your take on it. I think the bit of wood at the bottom is distracting however. Also, the slight barrel distortion is somewhat bothersome to me. I played around and corrected this and it does look much better.</td>', 'I really like this subject and your take on it. I think the bit of wood at the bottom is distracting however. Also, the slight barrel distortion is somewhat bothersome to me. I played around and corrected this and it does look much better.', '2003-07-29 22:46:43.000000', NULL, 1),
(369959, 30710, 2333, '<td valign="top">My favorite of this challenge! I just love your choice of framing, and yes, even though the subject is perfectly centered, this works for me.  The colors and DOF are perfect. Kudos.<br/>I feel that your choice of title really enhances the photo as well</td>', 'My favorite of this challenge! I just love your choice of framing, and yes, even though the subject is perfectly centered, this works for me.  The colors and DOF are perfect. Kudos.I feel that your choice of title really enhances the photo as well', '2003-07-29 22:49:17.000000', NULL, 1),
(369960, 30745, 2333, '<td valign="top">A beautiful abstract. i really like the tones. Nice work.</td>', 'A beautiful abstract. i really like the tones. Nice work.', '2003-07-29 22:50:32.000000', NULL, 1),
(369961, 30780, 2333, '<td valign="top">Like the framing. Beautiful rich tones. Neither overly sharp or too soft. Exposure is perfect. You should do well with this.</td>', 'Like the framing. Beautiful rich tones. Neither overly sharp or too soft. Exposure is perfect. You should do well with this.', '2003-07-29 22:52:24.000000', NULL, 1),
(369964, 30588, 2333, '<td valign="top">Nice Chicago scene. You found some great light. I think this submission could have more impact with just a bit more contrast and slightly more saturation.</td>', 'Nice Chicago scene. You found some great light. I think this submission could have more impact with just a bit more contrast and slightly more saturation.', '2003-07-29 22:56:04.000000', NULL, 1),
(369967, 30804, 2333, '<td valign="top">I like this shot, I can feel the anticipation! Would have been a great submission for "unanswered questions". <br/>I think the "(Uncropped)" detracts from an otherwise good title</td>', 'I like this shot, I can feel the anticipation! Would have been a great submission for "unanswered questions". I think the "(Uncropped)" detracts from an otherwise good title', '2003-07-29 23:00:05.000000', NULL, 1),
(369971, 30293, 2333, '<td valign="top">Perfect framing. very nice exposure and just the right level of sharpness. Possibly a bit oversaturated, but it does work here.</td>', 'Perfect framing. very nice exposure and just the right level of sharpness. Possibly a bit oversaturated, but it does work here.', '2003-07-29 23:04:04.000000', NULL, 1),
(369974, 30710, 3093, '<td valign="top">detail and texture is stunning</td>', 'detail and texture is stunning', '2003-07-29 23:07:55.000000', NULL, 1),
(369978, 30635, 2333, '<td valign="top">Nice perspective, good focus 7 exposure, pleasing tones. Could possibly benefit from just a bit more contrast, and just maybe a hint more saturation... no, contrast is enough.</td>', 'Nice perspective, good focus 7 exposure, pleasing tones. Could possibly benefit from just a bit more contrast, and just maybe a hint more saturation... no, contrast is enough.', '2003-07-29 23:11:08.000000', NULL, 1),
(369982, 30590, 2333, '<td valign="top">I very much ike the concept; there are a few things you could do to improve the execution. A difuse light source woiuld work better with the reflective skin of the snake, and a bit darker background would possibly work better; it is overexposed here. Did you use an incandescant light? The color balance looks quite reddish. You can correct this in software, or your camera may be able to compensate. If you have the camera''s white balance set to manual, it may have been fooled, this is not uncommon.</td>', 'I very much ike the concept; there are a few things you could do to improve the execution. A difuse light source woiuld work better with the reflective skin of the snake, and a bit darker background would possibly work better; it is overexposed here. Did you use an incandescant light? The color balance looks quite reddish. You can correct this in software, or your camera may be able to compensate. If you have the camera''s white balance set to manual, it may have been fooled, this is not uncommon.', '2003-07-29 23:18:24.000000', NULL, 1),
(370000, 30541, 9546, '<td valign="top">What magnificent color!!! Great detail.  How often we overlook the wonders of God''s creation.  One of my favorites.</td>', 'What magnificent color!!! Great detail.  How often we overlook the wonders of God''s creation.  One of my favorites.', '2003-07-29 23:25:46.000000', NULL, 1),
(370083, 30557, 6504, '<td valign="top">A very beautiful child.  Look at those sweet eyes!!!   I think this is the winner.</td>', 'A very beautiful child.  Look at those sweet eyes!!!   I think this is the winner.', '2003-07-30 00:34:22.000000', NULL, 1),
(370084, 30280, 7556, '<td valign="top">I like the perspective...</td>', 'I like the perspective...', '2003-07-30 00:35:54.000000', NULL, 1),
(370089, 30530, 6325, '<td valign="top">Looks like my house. We have three orange cats. This is so typical. I like the little swirl in the upper right. I would say that the colors are a little muted.</td>', 'Looks like my house. We have three orange cats. This is so typical. I like the little swirl in the upper right. I would say that the colors are a little muted.', '2003-07-30 00:43:32.000000', NULL, 1),
