(370091, 30293, 6325, '<td valign="top">Stunning. Love the detail and the wood tones.</td>', 'Stunning. Love the detail and the wood tones.', '2003-07-30 00:47:59.000000', NULL, 1),
(370092, 30462, 7556, '<td valign="top">I love the lighting! nice composition. my top pick...</td>', 'I love the lighting! nice composition. my top pick...', '2003-07-30 00:51:30.000000', NULL, 1),
(370093, 30750, 9582, '<td valign="top">This is my favorite of the "kitty face" photos. It is crisp and the composition is nice.</td>', 'This is my favorite of the "kitty face" photos. It is crisp and the composition is nice.', '2003-07-30 00:52:27.000000', NULL, 1),
