(373439, 30711, 5728, '<td valign="top">Very nice, I love the grainy B&amp;W effect. This almost looks like a painting.</td>', 'Very nice, I love the grainy B&W effect. This almost looks like a painting.', '2003-08-01 07:28:53.000000', NULL, 1),
(373515, 30462, 1202, '<td valign="top">This is a wonderful use of back light, which shows painstaking effort getting the right composition.  A winner all the way!  10</td>', 'This is a wonderful use of back light, which shows painstaking effort getting the right composition.  A winner all the way!  10', '2003-08-01 10:50:21.000000', NULL, 1),
