(373655, 30755, 3290, '<td valign="top">Nice detail and interesting viewpoint. My criticisms are shallow DOF (soft in the foreground_ and the lighting which causes the front petals to shadow those behind.</td>', 'Nice detail and interesting viewpoint. My criticisms are shallow DOF (soft in the foreground_ and the lighting which causes the front petals to shadow those behind.', '2003-08-01 14:40:22.000000', NULL, 1),
(373656, 30767, 3290, '<td valign="top">Nice. Pulling back a bit would have shown us all of the detail work on the sound box. But I still like this.</td>', 'Nice. Pulling back a bit would have shown us all of the detail work on the sound box. But I still like this.', '2003-08-01 14:41:07.000000', NULL, 1),
(373657, 30551, 3290, '<td valign="top">Lighting is harsh and it would be better without the empty space at the top. Colourful.</td>', 'Lighting is harsh and it would be better without the empty space at the top. Colourful.', '2003-08-01 14:42:01.000000', NULL, 1),
(373659, 30636, 3290, '<td valign="top">Cool. But a little hard to figure out. Not sure what would help - perhaps more contrast?</td>', 'Cool. But a little hard to figure out. Not sure what would help - perhaps more contrast?', '2003-08-01 14:42:40.000000', NULL, 1),
