(375265, 30490, 6388, '<td valign="top">too  bad you felt you had to explain yoarself in the title (darn literal DCPers to contend with, i understand).  really like the composotion of this, and the muted ighting up front works well.  good job.</td>', 'too  bad you felt you had to explain yoarself in the title (darn literal DCPers to contend with, i understand).  really like the composotion of this, and the muted ighting up front works well.  good job.', '2003-08-03 16:30:07.000000', NULL, 1),
(375266, 30804, 6388, '<td valign="top">the lighting needs work here.  without the aid of real lighting (welcome to Vegas!) this is tough to get even.  perhaps metering it on the unlit part would have helped.  You''re going to get reflections no matter what in this situation, so you might as well over-do it and add some detail in the shadows.  did you win anything?</td>', 'the lighting needs work here.  without the aid of real lighting (welcome to Vegas!) this is tough to get even.  perhaps metering it on the unlit part would have helped.  You''re going to get reflections no matter what in this situation, so you might as well over-do it and add some detail in the shadows.  did you win anything?', '2003-08-03 16:34:19.000000', NULL, 1),
(375267, 30580, 6388, '<td valign="top">i like it.  great colour obviously.  very well lit.  I cn almost taste them (yes I used to eat erasers as a kid, sue me).  bit soft onthe border; a 2 pixel black line inside the white one would help set it apart, in my opinion.</td>', 'i like it.  great colour obviously.  very well lit.  I cn almost taste them (yes I used to eat erasers as a kid, sue me).  bit soft onthe border; a 2 pixel black line inside the white one would help set it apart, in my opinion.', '2003-08-03 16:36:32.000000', NULL, 1),
(375271, 30525, 3290, '<td valign="top">I like this for its interesting perspective. I Can''t hellp feeling it would benefit from haiving the flower head lower in the frame, though. There seems to be a lot of noise in the sky.</td>', 'I like this for its interesting perspective. I Can''t hellp feeling it would benefit from haiving the flower head lower in the frame, though. There seems to be a lot of noise in the sky.', '2003-08-03 17:03:43.000000', NULL, 1),
(375272, 30810, 3290, '<td valign="top">Attractive, but would benefit from 1/2-1 stop less exposure, I think.</td>', 'Attractive, but would benefit from 1/2-1 stop less exposure, I think.', '2003-08-03 17:04:30.000000', NULL, 1),
(375273, 30714, 3290, '<td valign="top">Nice. I like th etxures in this - good use of B&amp;W. Well done.</td>', 'Nice. I like th etxures in this - good use of B&W. Well done.', '2003-08-03 17:06:03.000000', NULL, 1),
(375274, 30722, 3290, '<td valign="top">This is nice. I think the background is a bit of a distraxtion, and that some lighting which emphasised the string more would be good, but I like this.</td>', 'This is nice. I think the background is a bit of a distraxtion, and that some lighting which emphasised the string more would be good, but I like this.', '2003-08-03 17:08:25.000000', NULL, 1),
(375275, 30260, 3290, '<td valign="top">I thought of doing something like this, but didn''t. This isn''t a bad attempt, but I think it would have much more impact if the frame and tank were backlit - as it is, it looks like brown goo.</td>', 'I thought of doing something like this, but didn''t. This isn''t a bad attempt, but I think it would have much more impact if the frame and tank were backlit - as it is, it looks like brown goo.', '2003-08-03 17:10:37.000000', NULL, 1),
(375276, 30731, 3290, '<td valign="top">There''s some interesting texture in that door, which I think I''d like to see in a more close-up shot.</td>', 'There''s some interesting texture in that door, which I think I''d like to see in a more close-up shot.', '2003-08-03 17:11:25.000000', NULL, 1),
(375277, 30530, 3290, '<td valign="top">Good subject, harsh lighting.</td>', 'Good subject, harsh lighting.', '2003-08-03 17:11:53.000000', NULL, 1),
(375278, 30462, 3290, '<td valign="top">Oh, this *is* nice. Interesting perspective, great colours and some attractive lighting. Personally, I''d like it to be a tad sharper on the stamens  and a bit lighter, but this is still very nice. Well done. How did you do the lighting?</td>', 'Oh, this *is* nice. Interesting perspective, great colours and some attractive lighting. Personally, I''d like it to be a tad sharper on the stamens  and a bit lighter, but this is still very nice. Well done. How did you do the lighting?', '2003-08-03 17:13:44.000000', NULL, 1),
(375280, 30798, 3290, '<td valign="top">Since the subjects are translucent, I would like to see what this is like backlit with perhaps a coloured light. Right now, I think the lighting makes it a bit flat.</td>', 'Since the subjects are translucent, I would like to see what this is like backlit with perhaps a coloured light. Right now, I think the lighting makes it a bit flat.', '2003-08-03 17:15:12.000000', NULL, 1),
(375282, 30764, 3290, '<td valign="top">Nice abstract. Some good textures and colours there.</td>', 'Nice abstract. Some good textures and colours there.', '2003-08-03 17:15:49.000000', NULL, 1),
(375287, 30681, 3290, '<td valign="top">Pretty. Would work better with a tighter crop.</td>', 'Pretty. Would work better with a tighter crop.', '2003-08-03 17:17:45.000000', NULL, 1),
(375288, 30167, 3290, '<td valign="top">Pretty. I''d like to see a BIG version of this on the wall. Wait - maybe that would be the original :-)</td>', 'Pretty. I''d like to see a BIG version of this on the wall. Wait - maybe that would be the original :-)', '2003-08-03 17:19:24.000000', NULL, 1),
(375289, 30718, 3290, '<td valign="top">Nice textures and attractively saturated colours. I''d like to see it pulled back a little.</td>', 'Nice textures and attractively saturated colours. I''d like to see it pulled back a little.', '2003-08-03 17:20:22.000000', NULL, 1),
(375291, 30344, 806, '<td valign="top">The focus could be clearer, and I might have even rotated the image 90 deg CCW to have the heavier logs on the right of the frame.</td>', 'The focus could be clearer, and I might have even rotated the image 90 deg CCW to have the heavier logs on the right of the frame.', '2003-08-03 17:20:39.000000', NULL, 1),
(375298, 29960, 3290, '<td valign="top">Intense. Nice use of colour (or lack thereof) to emphasise the eyes.</td>', 'Intense. Nice use of colour (or lack thereof) to emphasise the eyes.', '2003-08-03 17:24:37.000000', NULL, 1),
(375301, 30563, 3290, '<td valign="top">Excellent. You can see exactly what it is without having to be shown too much. Good balance between what we see and what we don''t. Very good composition. This is the best shot I''ve seen so far - well done.<br/><br/><i>Message edited by author 2003-08-04 03:31:57.</i></td>', 'Excellent. You can see exactly what it is without having to be shown too much. Good balance between what we see and what we don''t. Very good composition. This is the best shot I''ve seen so far - well done.', '2003-08-03 17:26:10.000000', '2003-08-04 04:31:57.000000', 1),
(375304, 30769, 3290, '<td valign="top">Nice. Excellent rich colours and initmate study.</td>', 'Nice. Excellent rich colours and initmate study.', '2003-08-03 17:27:53.000000', NULL, 1),
(375305, 30667, 3290, '<td valign="top">Interesting view of a familiar subject.</td>', 'Interesting view of a familiar subject.', '2003-08-03 17:28:23.000000', NULL, 1),
(375307, 30763, 3290, '<td valign="top">Cool. Nicely seen - great composition.</td>', 'Cool. Nicely seen - great composition.', '2003-08-03 17:29:31.000000', NULL, 1),
(375310, 30293, 3290, '<td valign="top">Nice colour - would have worked better with a diagonal composition, I think.</td>', 'Nice colour - would have worked better with a diagonal composition, I think.', '2003-08-03 17:31:18.000000', NULL, 1),
(375313, 30710, 6624, '<td valign="top">wonderful texture, such old eyes...nice composition</td>', 'wonderful texture, such old eyes...nice composition', '2003-08-03 17:32:35.000000', NULL, 1),
(375314, 30557, 6624, '<td valign="top">epitome of childhood - nice image</td>', 'epitome of childhood - nice image', '2003-08-03 17:33:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
