(375320, 30223, 6624, '<td valign="top">very funny interesting shot</td>', 'very funny interesting shot', '2003-08-03 17:35:58.000000', NULL, 1),
(375321, 30223, 3290, '<td valign="top">I like the way you''ve done this, but two things spoil it: 1) the hand, 2) the shape of the frame, which lets you see the background. Plus the whole thing is too small.</td>', 'I like the way you''ve done this, but two things spoil it: 1) the hand, 2) the shape of the frame, which lets you see the background. Plus the whole thing is too small.', '2003-08-03 17:38:04.000000', NULL, 1),
