(375468, 30684, 1280, '<td valign="top">Interesting subject, and I like the "framed" idea.  T he subject doesn''t entirely fill the frame.</td>', 'Interesting subject, and I like the "framed" idea.  T he subject doesn''t entirely fill the frame.', '2003-08-03 19:32:26.000000', NULL, 1),
(375471, 30669, 5792, '<td valign="top">The color and composition of this frame is very nice. <br/> <br/>The tilted shell makes it appear to be the tortise on its way to beating the hare in that famous mythological race.</td>', 'The color and composition of this frame is very nice.  The tilted shell makes it appear to be the tortise on its way to beating the hare in that famous mythological race.', '2003-08-03 19:35:19.000000', NULL, 1),
(375472, 30342, 1280, '<td valign="top">Hey...my home town!  Actually I came  from da Bronx, but still a New Yorker till they lay my body down.  Nice job!</td>', 'Hey...my home town!  Actually I came  from da Bronx, but still a New Yorker till they lay my body down.  Nice job!', '2003-08-03 19:36:23.000000', NULL, 1),
(375473, 30590, 5792, '<td valign="top">This is a fine image, but seems a little washed out to me. That could be my monitor.  I like that way it is composed.</td>', 'This is a fine image, but seems a little washed out to me. That could be my monitor.  I like that way it is composed.', '2003-08-03 19:37:00.000000', NULL, 1),
(375474, 30152, 1280, '<td valign="top">Cute</td>', 'Cute', '2003-08-03 19:38:18.000000', NULL, 1),
(375475, 30685, 5792, '<td valign="top">The peppers may be "imperfect"  but the image is not. Kudos on a fine shot.</td>', 'The peppers may be "imperfect"  but the image is not. Kudos on a fine shot.', '2003-08-03 19:38:44.000000', NULL, 1),
(375476, 30636, 5792, '<td valign="top">Very artistic</td>', 'Very artistic', '2003-08-03 19:39:16.000000', NULL, 1),
