(375478, 30719, 1280, '<td valign="top">Good idea.  Lighting and contrast could be improved.</td>', 'Good idea.  Lighting and contrast could be improved.', '2003-08-03 19:40:32.000000', NULL, 1),
(375479, 30176, 5792, '<td valign="top">I have to say that "unzipping" is one of my favorite activities.<br/> <br/>This superb image only supports that. Sepia is great for this image. Excellant technical quality.</td>', 'I have to say that "unzipping" is one of my favorite activities. This superb image only supports that. Sepia is great for this image. Excellant technical quality.', '2003-08-03 19:43:07.000000', NULL, 1),
