(375485, 30718, 5792, '<td valign="top">I admire photographers with an "eye" such as yours. Beautifully composed.</td>', 'I admire photographers with an "eye" such as yours. Beautifully composed.', '2003-08-03 19:47:21.000000', NULL, 1),
(375488, 30011, 5792, '<td valign="top">Meets the challenge very well.</td>', 'Meets the challenge very well.', '2003-08-03 19:48:17.000000', NULL, 1),
(375489, 30714, 5792, '<td valign="top">The "69"n this image is good and making it B&amp;W is a very good. One of my favorites.</td>', 'The "69"n this image is good and making it B&W is a very good. One of my favorites.', '2003-08-03 19:50:59.000000', NULL, 1),
(375492, 30639, 1280, '<td valign="top">Pretty face!</td>', 'Pretty face!', '2003-08-03 19:51:56.000000', NULL, 1),
