(375494, 30808, 5792, '<td valign="top">A beautifully composed image. Technically good. <br/> <br/>Most viewers should like this one a lot even though flowers are overused at this site.</td>', 'A beautifully composed image. Technically good.  Most viewers should like this one a lot even though flowers are overused at this site.', '2003-08-03 19:53:50.000000', NULL, 1),
(375495, 30167, 1280, '<td valign="top">Nice rich tones.</td>', 'Nice rich tones.', '2003-08-03 19:54:30.000000', NULL, 1),
(375497, 30260, 1280, '<td valign="top">clever sense of humour!</td>', 'clever sense of humour!', '2003-08-03 19:58:55.000000', NULL, 1),
