(375512, 30774, 1280, '<td valign="top">Good lighting, colour, and texture.</td>', 'Good lighting, colour, and texture.', '2003-08-03 20:08:51.000000', NULL, 1),
(375514, 30718, 1280, '<td valign="top">Richly textured, and marvelous colours!</td>', 'Richly textured, and marvelous colours!', '2003-08-03 20:10:05.000000', NULL, 1),
(375528, 30623, 8860, '<td valign="top">This kind of shot just has to be sharp and in focus. Composition is also too central and would be more effective if you panned over to the left and slightly upwards.</td>', 'This kind of shot just has to be sharp and in focus. Composition is also too central and would be more effective if you panned over to the left and slightly upwards.', '2003-08-03 20:30:49.000000', NULL, 1),
(375561, 29960, 7969, '<td valign="top">now i was sure i commented earlier-- hate when that happens, great lighting and composition, the green eyes really make it vibrant.  great job.</td>', 'now i was sure i commented earlier-- hate when that happens, great lighting and composition, the green eyes really make it vibrant.  great job.', '2003-08-03 21:17:19.000000', NULL, 1),
(375562, 30776, 7969, '<td valign="top">WOW thats all I can say, IMO this is by far the best shot.  Meets the challenge, colors and lighting are fabulous, the light blue background gives the feeling like the rocks (?) are floating somehow.  This shot has a feeling of depth and suspension that I think is phenomenal.</td>', 'WOW thats all I can say, IMO this is by far the best shot.  Meets the challenge, colors and lighting are fabulous, the light blue background gives the feeling like the rocks (?) are floating somehow.  This shot has a feeling of depth and suspension that I think is phenomenal.', '2003-08-03 21:17:49.000000', NULL, 1),
